body {
  margin: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: #f9fafb;
  color: #111827;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

#app {
  text-align: center;
  padding: 2rem;
  background: white;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
  width: 100%;
  max-width: 1200px;
}

import { setupHeader } from './components/Header.js';
import { renderMetrics } from './components/MetricCards.js';
import { renderChart } from './components/InventoryChart.js';
import { renderTable } from './components/ProductTable.js';
import { openProductModal } from './components/ProductModal.js';

let state = JSON.parse(localStorage.getItem('inventory-app-state')) || {
  products: []
};

const saveState = () => {
  localStorage.setItem('inventory-app-state', JSON.stringify(state));
};

const refreshUI = () => {
  const metricsContainer = document.getElementById('metriccards-container');
  const chartContainer = document.getElementById('inventorychart-container');
  const tableContainer = document.getElementById('producttable-container');

  if (metricsContainer) renderMetrics(state.products);
  if (chartContainer) renderChart('inventorychart-container', state.products);
  if (tableContainer) renderTable(state.products);
};

window.addEventListener('add-product', (e) => {
  state.products.push(e.detail);
  saveState();
  refreshUI();
});

window.addEventListener('delete-product', (e) => {
  state.products = state.products.filter(p => p.id !== e.detail.id);
  saveState();
  refreshUI();
});

const init = () => {
  setupHeader();

  const addBtn = document.getElementById('add-product-btn');
  if (addBtn) {
    addBtn.addEventListener('click', () => {
      openProductModal();
    });
  }

  refreshUI();
};

document.addEventListener('DOMContentLoaded', init);

export function setupHeader() {
  const headerContainer = document.getElementById('header-container');
  if (!headerContainer) return;

  headerContainer.innerHTML = `
    <nav class="bg-slate-900 text-white p-4 shadow-lg">
      <div class="container mx-auto flex justify-between items-center">
        <h1 class="text-xl font-bold tracking-tight">InventoryManager</h1>
        <div class="flex gap-4">
          <button id="nav-dashboard" class="px-4 py-2 rounded hover:bg-slate-800 transition-colors">
            Dashboard
          </button>
          <button id="nav-products" class="px-4 py-2 rounded hover:bg-slate-800 transition-colors">
            Products
          </button>
        </div>
      </div>
    </nav>
  `;

  document.getElementById('nav-dashboard').addEventListener('click', () => {
    window.dispatchEvent(new CustomEvent('navigate', { detail: { view: 'dashboard' } }));
  });

  document.getElementById('nav-products').addEventListener('click', () => {
    window.dispatchEvent(new CustomEvent('navigate', { detail: { view: 'products' } }));
  });
}

import { Chart, registerables } from 'chart.js';

Chart.register(...registerables);

let chartInstance = null;

export function renderChart(containerId, inventoryData) {
  const container = document.getElementById(containerId);
  if (!container) return;

  container.innerHTML = '<canvas id="inventory-chart-canvas"></canvas>';
  const canvas = document.getElementById('inventory-chart-canvas');

  if (chartInstance) {
    chartInstance.destroy();
  }

  const labels = inventoryData.map(item => item.name);
  const data = inventoryData.map(item => item.quantity);

  chartInstance = new Chart(canvas, {
    type: 'bar',
    data: {
      labels: labels,
      datasets: [{
        label: 'Stock Quantity',
        data: data,
        backgroundColor: 'rgba(59, 130, 246, 0.6)',
        borderColor: 'rgba(59, 130, 246, 1)',
        borderWidth: 1
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          beginAtZero: true,
          ticks: { precision: 0 }
        }
      }
    }
  });
}

export function renderMetrics(products) {
  const container = document.getElementById('metriccards-container');
  if (!container) return;

  const totalProducts = products.length;
  const lowStock = products.filter(p => p.quantity < 10).length;
  const totalValue = products.reduce((sum, p) => sum + (p.price * p.quantity), 0);

  container.innerHTML = `
    <div class="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
      <div class="bg-white p-6 rounded-lg shadow border border-gray-200">
        <h3 class="text-sm font-medium text-gray-500 uppercase">Total Products</h3>
        <p class="text-3xl font-bold text-gray-900">${totalProducts}</p>
      </div>
      <div class="bg-white p-6 rounded-lg shadow border border-gray-200">
        <h3 class="text-sm font-medium text-gray-500 uppercase">Low Stock</h3>
        <p class="text-3xl font-bold text-red-600">${lowStock}</p>
      </div>
      <div class="bg-white p-6 rounded-lg shadow border border-gray-200">
        <h3 class="text-sm font-medium text-gray-500 uppercase">Inventory Value</h3>
        <p class="text-3xl font-bold text-gray-900">$${totalValue.toLocaleString()}</p>
      </div>
    </div>
  `;
}

export function renderTable(products) {
  const container = document.getElementById('producttable-container');
  if (!container) return;

  const html = `
    <div class="bg-white shadow rounded-lg overflow-hidden">
      <div class="p-4 border-b flex justify-between items-center">
        <input 
          type="text" 
          id="product-search" 
          placeholder="Search products..." 
          class="border rounded px-3 py-2 w-64"
        />
        <button id="add-product-btn" class="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">
          Add Product
        </button>
      </div>
      <table class="min-w-full divide-y divide-gray-200">
        <thead class="bg-gray-50">
          <tr>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Name</th>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Category</th>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Stock</th>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
          </tr>
        </thead>
        <tbody class="bg-white divide-y divide-gray-200">
          ${products.map(product => `
            <tr>
              <td class="px-6 py-4 whitespace-nowrap">${product.name}</td>
              <td class="px-6 py-4 whitespace-nowrap">${product.category}</td>
              <td class="px-6 py-4 whitespace-nowrap">${product.stock}</td>
              <td class="px-6 py-4 whitespace-nowrap">
                <button 
                  data-id="${product.id}" 
                  class="delete-btn text-red-600 hover:text-red-900"
                >
                  Delete
                </button>
              </td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;

  container.innerHTML = html;

  container.querySelectorAll('.delete-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const id = e.target.getAttribute('data-id');
      window.dispatchEvent(new CustomEvent('delete-product', { detail: { id } }));
    });
  });

  document.getElementById('product-search').addEventListener('input', (e) => {
    const term = e.target.value.toLowerCase();
    window.dispatchEvent(new CustomEvent('filter-products', { detail: { term } }));
  });
}

export function openProductModal(product = null) {
  const overlay = document.createElement('div');
  overlay.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50';
  overlay.id = 'product-modal-overlay';

  const modal = document.createElement('div');
  modal.className = 'bg-white rounded-lg shadow-xl p-6 w-full max-w-md';

  const isEditing = !!product;

  modal.innerHTML = `
    <h2 class="text-xl font-bold mb-4">${isEditing ? 'Edit Product' : 'Add New Product'}</h2>
    <form id="product-form" class="space-y-4">
      <input type="hidden" id="edit-id" value="${product?.id || ''}">
      <div>
        <label class="block text-sm font-medium text-gray-700">Name</label>
        <input type="text" id="name" value="${product?.name || ''}" required class="w-full border rounded p-2">
      </div>
      <div>
        <label class="block text-sm font-medium text-gray-700">Stock</label>
        <input type="number" id="stock" value="${product?.stock || 0}" required class="w-full border rounded p-2">
      </div>
      <div>
        <label class="block text-sm font-medium text-gray-700">Price</label>
        <input type="number" id="price" value="${product?.price || 0}" step="0.01" required class="w-full border rounded p-2">
      </div>
      <div class="flex justify-end space-x-2 mt-6">
        <button type="button" id="cancel-btn" class="px-4 py-2 bg-gray-200 rounded">Cancel</button>
        <button type="submit" class="px-4 py-2 bg-blue-600 text-white rounded">${isEditing ? 'Save' : 'Add'}</button>
      </div>
    </form>
  `;

  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  const closeModal = () => overlay.remove();

  overlay.querySelector('#cancel-btn').addEventListener('click', closeModal);

  modal.querySelector('#product-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const formData = {
      id: document.getElementById('edit-id').value || Date.now().toString(),
      name: document.getElementById('name').value,
      stock: parseInt(document.getElementById('stock').value, 10),
      price: parseFloat(document.getElementById('price').value)
    };

    window.dispatchEvent(new CustomEvent('add-product', { detail: formData }));
    closeModal();
  });
}
